package com.matchcontrol.core

import org.junit.Assert.*
import org.junit.Test

class SandboxRulesTest {
 private val now=2_000_000_000_000L
 private fun seed()=DemoEngine.seed(now)
 private fun request(s: Snapshot,n: Int=1,id: String="request-1",stake: Long=10_000)=BetRequest(id,stake,s.outcomes.filter {it.market==MarketType.WINNER && it.key=="1" && it.open}.take(n).associate {it.id to it.odds})
 @Test fun initialBalanceAndExactDecimals() {assertEquals(1_000_000L,seed().balance);assertEquals(12345L,parseCredits("123.45"));assertEquals("123.45",credits(12345));assertEquals(18500L,BettingRules.returns(10000,listOf(18500)))}
 @Test fun simpleWinCreditsOnce() {val (placed,b)=DemoEngine.place(seed(),request(seed()),now);val done=DemoLab.finish(placed,b.picks.single().matchId,2,1);assertEquals(BetStatus.WON,done.bets.single().status);assertEquals(1_008_500L,done.balance);assertEquals(done,DemoEngine.settle(done))}
 @Test fun simpleLossNoReturn() {val(s,b)=DemoEngine.place(seed(),request(seed()),now);val done=DemoLab.finish(s,b.picks.single().matchId,0,1);assertEquals(BetStatus.LOST,done.bets.single().status);assertEquals(990000,done.balance)}
 @Test fun combinedRequiresAllResultsAndUsesLockedProduct() {val(s,b)=DemoEngine.place(seed(),request(seed(),2),now);val first=DemoLab.finish(s,b.picks[0].matchId,2,1);assertEquals(BetStatus.PENDING,first.bets.single().status);val done=DemoLab.finish(first,b.picks[1].matchId,3,0);assertEquals(BetStatus.WON,done.bets.single().status);assertEquals(34225L,done.bets.single().returned)}
 @Test fun allVoidsRefundAndMixedVoidRemovesOnlyOneOdd() {val(s,b)=DemoEngine.place(seed(),request(seed(),2),now);val first=DemoLab.cancel(s,b.picks[0].matchId);val done=DemoLab.cancel(first,b.picks[1].matchId);assertEquals(BetStatus.VOID,done.bets.single().status);assertEquals(1_000_000L,done.balance);val win=DemoLab.finish(first,b.picks[1].matchId,2,1);assertEquals(18500L,win.bets.single().returned)}
 @Test fun retryReturnsSameBetAndDoesNotDebitTwice() {val r=request(seed());val(s,b)=DemoEngine.place(seed(),r,now);val(second,same)=DemoEngine.place(s,r,now);assertEquals(b,same);assertEquals(s,second)}
 @Test fun retryWithDifferentPayloadIsRejected() {val r=request(seed());val(s,_)=DemoEngine.place(seed(),r,now);assertThrows(IllegalArgumentException::class.java) {DemoEngine.place(s,r.copy(stake=20000),now)}}
 @Test fun insufficientBalanceAndInvalidPrecisionRejected() {assertThrows(IllegalArgumentException::class.java) {DemoEngine.place(seed(),request(seed(),stake=2_000_000),now)};assertThrows(ArithmeticException::class.java) {parseCredits("1.001")}}
 @Test fun sameEventAndChangedOddsRejected() {val s=seed();val available=s.outcomes.filter {it.open};val same=available.take(2).associate {it.id to it.odds};assertThrows(IllegalArgumentException::class.java) {DemoEngine.place(s,BetRequest("same",10000,same),now)};val r=request(s);assertThrows(IllegalArgumentException::class.java) {DemoEngine.place(s,r.copy(outcomes=r.outcomes.mapValues {it.value+1}),now)}}
 @Test fun closedMarketsAndStartedEventsRejected() {val s=seed();val r=request(s);assertThrows(IllegalArgumentException::class.java) {DemoEngine.place(s.copy(outcomes=s.outcomes.map {it.copy(open=false)}),r,now)};assertThrows(IllegalArgumentException::class.java) {DemoEngine.place(s,r,now+10*86_400_000L)}}
 @Test fun incompleteOrUnverifiedResultsNeverSettle() {val(s,b)=DemoEngine.place(seed(),request(seed()),now);val match=s.fixtures.first {it.id==b.picks[0].matchId};assertEquals(BetStatus.PENDING,BettingRules.result(match.copy(status=FixtureStatus.FINAL,homeScore=2,awayScore=0),b.picks[0]));assertEquals(BetStatus.PENDING,BettingRules.result(match.copy(status=FixtureStatus.FINAL,homeScore=2,verified=true),b.picks[0]))}
 @Test fun allMarketRules() {val s=seed();val f=s.fixtures[0].copy(status=FixtureStatus.FINAL,homeScore=2,awayScore=1,verified=true);s.outcomes.filter {it.matchId==f.id}.forEach {o->val p=Pick(o.id,f.id,o.market,o.key,o.label,"x",o.odds);val win=o.key in when(o.market) {MarketType.WINNER->setOf("1");MarketType.DOUBLE_CHANCE->setOf("1X","12");MarketType.OVER_UNDER_15,MarketType.OVER_UNDER_25->setOf("OVER");MarketType.BOTH_SCORE->setOf("YES")};assertEquals(if(win) BetStatus.WON else BetStatus.LOST,BettingRules.result(f,p))}}
 @Test fun resetIsExplicitAuditableAndIdempotent() {val s=seed().copy(balance=50000);val reset=DemoEngine.reset(s,"reset");assertEquals(1_000_000,reset.balance);assertEquals("RESET",reset.transactions.last().kind);assertEquals(reset,DemoEngine.reset(reset,"reset"));val(placed,_)=DemoEngine.place(seed(),request(seed()),now);assertThrows(IllegalArgumentException::class.java) {DemoEngine.reset(placed,"bad")}}
 @Test fun noCreditRoundingUpAndOddsBounds() {assertEquals(101L,BettingRules.returns(101,listOf(10001)));assertThrows(IllegalArgumentException::class.java) {BettingRules.totalOdds(listOf(0))}}
 @Test fun newRoundNeverOverwritesExistingBetsOrOutcomes() {val(s,b)=DemoEngine.place(seed(),request(seed()),now);val added=DemoLab.newRound(s,now+86_400_000);assertEquals(s.bets,added.bets);assertEquals(s.balance,added.balance);assertEquals(12,added.fixtures.map {it.id}.distinct().size);assertEquals(s.outcomes.size*2,added.outcomes.map {it.id}.distinct().size);assertTrue(added.fixtures.any {it.id==b.picks[0].matchId})}
 @Test fun realResultsRequireRegulationScoreAndNeverUseExtraTimeForWinner() {val(s,b)=DemoEngine.place(seed(),request(seed()),now);val f=s.fixtures[0].copy(source="API_FOOTBALL",status=FixtureStatus.FINAL,homeScore=3,awayScore=2,verified=true);assertEquals(BetStatus.PENDING,BettingRules.result(f,b.picks[0]));assertEquals(BetStatus.LOST,BettingRules.result(f.copy(regulationHomeScore=1,regulationAwayScore=1),b.picks[0]))}
}
